// Simple in-memory store standing in for a database.
// `globalThis` keeps the value stable across dev-mode module reloads.

type PreferenceStore = { notificationsEnabled: boolean }

const store = (globalThis as typeof globalThis & {
  __preferences?: PreferenceStore
}).__preferences ??= { notificationsEnabled: false }

export async function getNotificationPreference(): Promise<boolean> {
  return store.notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  store.notificationsEnabled = enabled
}

