'use server'

import { revalidatePath } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from '@/lib/preferences'

export async function toggleNotifications() {
  const current = await getNotificationPreference()
  await setNotificationPreference(!current)

  // Refresh the current page's data without navigating away.
  // revalidatePath purges the cached data for this route, so the page
  // re-renders with the updated preference as soon as the action completes.
  revalidatePath('/')
}

