import { toggleNotifications } from './actions'
import { getNotificationPreference } from '@/lib/preferences'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently{' '}
        <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

